-- Migration 27: VYBE Tickets — trust and money foundation. Additive and re-runnable; no existing row is rewritten except the
-- one-time backfill of order pricing fields (organizer_net_cents = subtotal_cents, commission 0) on orders made before it.
--
-- 1. Fee policies: versioned, immutable commercial terms (organiser-paid commission and/or buyer-paid fee). Every order
--    stores the policy it was priced under and a full pricing snapshot; changing terms never alters an existing order.
--    Platform v1 reproduces the terms already live (buyer fee 5 % + R3.00, no organiser commission).
-- 2. Double-entry journal (journal_entries + journal_lines): every money movement balances to zero per entry (checked at
--    commit), lines are append-only, and each entry carries an idempotency key, so a retried webhook or worker can never
--    post twice. The older single-entry ledger_entries stays as the organiser sub-ledger (payout_balance reads it); the
--    reconciler checks the two agree.
-- 3. Payment notifications: every verified provider notification is recorded once per (provider, transaction, status);
--    reconciliation_exceptions is the queue for anything that needs a person (amount mismatch, paid after the hold lapsed
--    on a sold-out event, ledger disagreements, stuck refunds).
-- 4. Ticket-sales review: paid ticket sales need VYBE's approval of the event (submitted → under review → approved;
--    rejected / suspended / reinstated), with evidence and an append-only decision log. Free tickets are unaffected.
--    Reviewers cannot approve events they host or belong to. Lineup entries carry a verification status and history.
-- 5. Admission: event staff (scanners), an audit row for every scan, a scan rate limit, event-bound redemption, and ticket
--    codes are no longer readable by organisers (only the holder gets their code, through my_ticket_code).
-- 6. Payouts: refunds already owed are deducted from what can be withdrawn; one request at a time per payee (locked);
--    no payout within the cooling-off period after bank details change; the approver cannot be the requester; above
--    payout_dual_control_cents a second admin must confirm the transfer; the balance is re-checked at confirmation.
--
-- Rollback: this migration only adds objects and replaces function bodies. To roll back, re-run the function definitions
-- from migrations 6 and 8 (create_order, issue_tickets, fulfill_order, check_in_ticket, request_refund, refund_finish,
-- cancel_event_with_refunds, resolve_dispute, payout_balance, request_payout, admin_decide_payout, admin_mark_payout_paid,
-- admin_add_adjustment, admin_set_config) and `grant select on public.tickets to authenticated`. The new tables can stay.

-- ---------------------------------------------------------------- settings
alter table public.platform_config add column if not exists require_sales_review boolean not null default true;
alter table public.platform_config add column if not exists payout_dual_control_cents bigint not null default 500000 check (payout_dual_control_cents >= 0);
alter table public.platform_config add column if not exists payout_account_cooloff_hours integer not null default 72 check (payout_account_cooloff_hours between 0 and 720);

-- ---------------------------------------------------------------- 1. fee policies
create table if not exists public.fee_policies (
  id uuid primary key default gen_random_uuid(),
  scope text not null check (scope in ('platform', 'organization', 'event')),
  organization_id uuid references public.organizations(id) on delete restrict,
  event_id uuid references public.events(id) on delete restrict,
  name text not null check (char_length(name) between 2 and 80),
  commission_bps integer not null default 0 check (commission_bps between 0 and 3000),
  commission_fixed_cents integer not null default 0 check (commission_fixed_cents between 0 and 100000),
  commission_per_ticket_cents integer not null default 0 check (commission_per_ticket_cents between 0 and 100000),
  buyer_fee_enabled boolean not null default false,
  buyer_fee_bps integer not null default 0 check (buyer_fee_bps between 0 and 3000),
  buyer_fee_fixed_cents integer not null default 0 check (buyer_fee_fixed_cents between 0 and 100000),
  buyer_fee_per_ticket_cents integer not null default 0 check (buyer_fee_per_ticket_cents between 0 and 100000),
  -- What the commission percentage applies to: the ticket face value actually charged (after any discount), excluding the
  -- buyer fee. Kept as data so a future contract basis is explicit rather than assumed.
  commission_base text not null default 'ticket_subtotal' check (commission_base in ('ticket_subtotal')),
  effective_from timestamptz not null default now(),
  retired_at timestamptz,
  note text not null default '' check (char_length(note) <= 500),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  check ((scope = 'platform' and organization_id is null and event_id is null)
      or (scope = 'organization' and organization_id is not null and event_id is null)
      or (scope = 'event' and event_id is not null and organization_id is null)),
  check (buyer_fee_enabled or (buyer_fee_bps = 0 and buyer_fee_fixed_cents = 0 and buyer_fee_per_ticket_cents = 0))
);
create index if not exists fee_policies_lookup_idx on public.fee_policies (scope, organization_id, event_id, effective_from desc);
alter table public.fee_policies enable row level security;
drop policy if exists fee_policies_read on public.fee_policies;
create policy fee_policies_read on public.fee_policies for select to authenticated
  using (public.is_admin() or (organization_id is not null and public.org_role(organization_id) in ('owner', 'admin'))
         or (event_id is not null and public.can_manage_event(event_id)));
revoke all on public.fee_policies from anon, authenticated;
grant select on public.fee_policies to authenticated;

-- Terms are immutable once written; the only change allowed is retiring a version.
create or replace function public.trg_fee_policy_immutable() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then raise exception 'Fee policies cannot be deleted; retire them instead'; end if;
  if (to_jsonb(new) - 'retired_at') is distinct from (to_jsonb(old) - 'retired_at') then raise exception 'Fee policies are immutable; create a new version'; end if;
  if old.retired_at is not null then raise exception 'This fee policy is already retired'; end if;
  return new;
end $$;
drop trigger if exists fee_policy_immutable on public.fee_policies;
create trigger fee_policy_immutable before update or delete on public.fee_policies for each row execute function public.trg_fee_policy_immutable();

-- Platform v1 = the terms already in force (from platform_config): buyer fee, no organiser commission.
insert into public.fee_policies (scope, name, buyer_fee_enabled, buyer_fee_bps, buyer_fee_fixed_cents, commission_bps, effective_from, note)
select 'platform', 'Platform v1 (launch terms)', (c.fee_bps > 0 or c.fee_fixed_cents > 0), c.fee_bps, c.fee_fixed_cents, 0, timestamptz '2026-10-19 00:00:00+00',
       'Migrated from platform_config at migration 27: buyer pays the service fee; organisers pay no commission.'
from public.platform_config c
where c.id and not exists (select 1 from public.fee_policies where scope = 'platform');

-- The policy that applies to an event right now: event-specific, else the organisation's, else the platform's.
create or replace function public.fee_policy_for(p_event uuid, p_at timestamptz default now()) returns public.fee_policies
language sql stable security definer set search_path = '' as $$
  select f.* from public.fee_policies f, public.events e
  where e.id = p_event and f.effective_from <= p_at and (f.retired_at is null or f.retired_at > p_at)
    and ((f.scope = 'event' and f.event_id = e.id) or (f.scope = 'organization' and f.organization_id = e.organization_id) or f.scope = 'platform')
  order by case f.scope when 'event' then 0 when 'organization' then 1 else 2 end, f.effective_from desc
  limit 1;
$$;

-- Half-up rounding of a basis-point share of a non-negative integer amount (exact integer arithmetic; no floats).
create or replace function public.bps_of(p_amount bigint, p_bps integer) returns bigint
language sql immutable set search_path = '' as $$
  select div(p_amount::numeric * p_bps + 5000, 10000)::bigint;   -- exact: integer division after adding half
$$;

-- Prices an order under a policy. Pure: the same inputs always give the same snapshot (mirrored in src/lib/pricing.ts).
create or replace function public.price_order(p_policy public.fee_policies, p_subtotal bigint, p_units integer, p_vat_registered boolean, p_vat_bps integer) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare buyer_fee bigint := 0; commission bigint := 0; fee_vat bigint := 0; commission_vat bigint := 0;
begin
  if p_subtotal < 0 or p_units < 0 then raise exception 'invalid pricing input'; end if;
  if p_subtotal > 0 then
    if p_policy.buyer_fee_enabled then
      buyer_fee := public.bps_of(p_subtotal, p_policy.buyer_fee_bps) + p_policy.buyer_fee_fixed_cents + p_policy.buyer_fee_per_ticket_cents::bigint * p_units;
    end if;
    commission := least(p_subtotal, public.bps_of(p_subtotal, p_policy.commission_bps) + p_policy.commission_fixed_cents + p_policy.commission_per_ticket_cents::bigint * p_units);
    if p_vat_registered then           -- platform charges are VAT-inclusive; the VAT part is a liability, not revenue
      fee_vat := div(buyer_fee::numeric * p_vat_bps + div(10000 + p_vat_bps, 2), 10000 + p_vat_bps)::bigint;
      commission_vat := div(commission::numeric * p_vat_bps + div(10000 + p_vat_bps, 2), 10000 + p_vat_bps)::bigint;
    end if;
  end if;
  return jsonb_build_object(
    'policy_id', p_policy.id, 'policy_name', p_policy.name, 'policy_scope', p_policy.scope, 'commission_base', p_policy.commission_base,
    'commission_bps', p_policy.commission_bps, 'commission_fixed_cents', p_policy.commission_fixed_cents, 'commission_per_ticket_cents', p_policy.commission_per_ticket_cents,
    'buyer_fee_enabled', p_policy.buyer_fee_enabled, 'buyer_fee_bps', p_policy.buyer_fee_bps, 'buyer_fee_fixed_cents', p_policy.buyer_fee_fixed_cents,
    'buyer_fee_per_ticket_cents', p_policy.buyer_fee_per_ticket_cents, 'vat_registered', p_vat_registered, 'vat_bps', case when p_vat_registered then p_vat_bps else 0 end,
    'rounding', 'half_up_per_order', 'currency', 'ZAR', 'units', p_units,
    'subtotal_cents', p_subtotal, 'buyer_fee_cents', buyer_fee, 'buyer_fee_vat_cents', fee_vat, 'commission_cents', commission, 'commission_vat_cents', commission_vat,
    'organizer_net_cents', p_subtotal - commission, 'total_cents', p_subtotal + buyer_fee);
end $$;

alter table public.orders add column if not exists fee_policy_id uuid references public.fee_policies(id) on delete restrict;
alter table public.orders add column if not exists pricing jsonb;
alter table public.orders add column if not exists commission_cents bigint not null default 0 check (commission_cents >= 0);
alter table public.orders add column if not exists commission_vat_cents bigint not null default 0 check (commission_vat_cents >= 0);
alter table public.orders add column if not exists organizer_net_cents bigint check (organizer_net_cents is null or organizer_net_cents >= 0);
update public.orders set organizer_net_cents = subtotal_cents where organizer_net_cents is null;
alter table public.orders drop constraint if exists orders_net_le_subtotal;
alter table public.orders add constraint orders_net_le_subtotal check (organizer_net_cents is null or organizer_net_cents + commission_cents = subtotal_cents);

-- Admin: write a new version (the previous one at the same scope is retired at the new one's start).
create or replace function public.admin_create_fee_policy(p jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_id uuid; sc text := coalesce(p->>'scope', 'platform'); org uuid := nullif(p->>'organization_id', '')::uuid; ev uuid := nullif(p->>'event_id', '')::uuid;
        starts timestamptz := coalesce(nullif(p->>'effective_from', '')::timestamptz, now());
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if starts < now() - interval '1 minute' then raise exception 'New terms cannot start in the past'; end if;
  if coalesce(p->>'note', '') = '' then raise exception 'Say why the terms are changing (note)'; end if;
  insert into public.fee_policies (scope, organization_id, event_id, name, commission_bps, commission_fixed_cents, commission_per_ticket_cents,
                                   buyer_fee_enabled, buyer_fee_bps, buyer_fee_fixed_cents, buyer_fee_per_ticket_cents, effective_from, note, created_by)
  values (sc, case when sc = 'organization' then org end, case when sc = 'event' then ev end, coalesce(nullif(p->>'name', ''), 'Terms ' || to_char(starts, 'YYYY-MM-DD')),
          coalesce((p->>'commission_bps')::int, 0), coalesce((p->>'commission_fixed_cents')::int, 0), coalesce((p->>'commission_per_ticket_cents')::int, 0),
          coalesce((p->>'buyer_fee_enabled')::boolean, false), coalesce((p->>'buyer_fee_bps')::int, 0), coalesce((p->>'buyer_fee_fixed_cents')::int, 0),
          coalesce((p->>'buyer_fee_per_ticket_cents')::int, 0), starts, left(p->>'note', 500), auth.uid())
  returning id into new_id;
  update public.fee_policies set retired_at = starts
   where id <> new_id and retired_at is null and scope = sc and organization_id is not distinct from case when sc = 'organization' then org end
     and event_id is not distinct from case when sc = 'event' then ev end and effective_from < starts;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'fee_policy.created', 'fee_policy', new_id, p);
  return new_id;
end $$;

-- Admin: preview what a set of terms would do to an order, without saving anything (the commercial calculator).
create or replace function public.preview_pricing(p jsonb, p_subtotal bigint, p_units integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare f public.fee_policies; cfg public.platform_config;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into cfg from public.platform_config where id;
  f.id := null; f.name := 'Preview'; f.scope := 'platform'; f.commission_base := 'ticket_subtotal';
  f.commission_bps := coalesce((p->>'commission_bps')::int, 0); f.commission_fixed_cents := coalesce((p->>'commission_fixed_cents')::int, 0);
  f.commission_per_ticket_cents := coalesce((p->>'commission_per_ticket_cents')::int, 0); f.buyer_fee_enabled := coalesce((p->>'buyer_fee_enabled')::boolean, false);
  f.buyer_fee_bps := coalesce((p->>'buyer_fee_bps')::int, 0); f.buyer_fee_fixed_cents := coalesce((p->>'buyer_fee_fixed_cents')::int, 0);
  f.buyer_fee_per_ticket_cents := coalesce((p->>'buyer_fee_per_ticket_cents')::int, 0);
  return public.price_order(f, p_subtotal, p_units, cfg.vat_registered, cfg.vat_rate_bps);
end $$;

-- What an event's managers are charged, in plain terms (the resolved policy; no other organisation's contract is visible).
create or replace function public.event_fee_terms(p_event uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare f public.fee_policies;
begin
  if not (public.is_admin() or public.can_manage_event(p_event)) then raise exception 'forbidden' using errcode = '42501'; end if;
  f := public.fee_policy_for(p_event);
  if f.id is null then return null; end if;
  return jsonb_build_object('name', f.name, 'scope', f.scope, 'effective_from', f.effective_from, 'commission_bps', f.commission_bps,
    'commission_fixed_cents', f.commission_fixed_cents, 'commission_per_ticket_cents', f.commission_per_ticket_cents, 'buyer_fee_enabled', f.buyer_fee_enabled,
    'buyer_fee_bps', f.buyer_fee_bps, 'buyer_fee_fixed_cents', f.buyer_fee_fixed_cents, 'buyer_fee_per_ticket_cents', f.buyer_fee_per_ticket_cents, 'commission_base', f.commission_base);
end $$;

-- ---------------------------------------------------------------- 2. double-entry journal
create table if not exists public.journal_entries (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('sale', 'refund', 'oversold_hold', 'chargeback', 'payout', 'adjustment')),
  idempotency_key text not null unique check (char_length(idempotency_key) between 3 and 120),
  event_id uuid references public.events(id) on delete restrict,
  order_id uuid references public.orders(id) on delete restrict,
  refund_id uuid references public.refunds(id) on delete restrict,
  payout_id uuid references public.payouts(id) on delete restrict,
  dispute_id uuid references public.disputes(id) on delete restrict,
  fee_policy_id uuid references public.fee_policies(id) on delete restrict,
  currency text not null default 'ZAR' check (currency = 'ZAR'),
  memo text not null default '' check (char_length(memo) <= 300),
  created_by uuid,
  created_at timestamptz not null default now()
);
create index if not exists journal_entries_order_idx on public.journal_entries (order_id) where order_id is not null;
create index if not exists journal_entries_time_idx on public.journal_entries (created_at);

-- Accounts (signed amounts: debit +, credit −).
--   platform_cash            asset: money held at the payment providers and in VYBE's bank
--   organizer_payable        liability, one sub-account per payee (organisation or person)
--   refunds_payable          liability: money owed back to buyers outside an organiser's sales (e.g. paid after a hold lapsed)
--   buyer_fee_revenue        income: buyer service fees, excluding VAT
--   commission_revenue       income: organiser commission, excluding VAT
--   vat_payable              liability: VAT on VYBE's own charges
--   chargeback_losses        expense: chargebacks VYBE absorbs
--   adjustments              expense/income: approved manual corrections
create table if not exists public.journal_lines (
  id bigint generated always as identity primary key,
  entry_id bigint not null references public.journal_entries(id) on delete restrict,
  account text not null check (account in ('platform_cash', 'organizer_payable', 'refunds_payable', 'buyer_fee_revenue', 'commission_revenue', 'vat_payable', 'chargeback_losses', 'adjustments')),
  organization_id uuid references public.organizations(id) on delete restrict,
  payee_user uuid references public.profiles(id) on delete restrict,
  amount_cents bigint not null check (amount_cents <> 0),
  check ((account = 'organizer_payable') = (organization_id is not null or payee_user is not null)),
  check (organization_id is null or payee_user is null)
);
create index if not exists journal_lines_entry_idx on public.journal_lines (entry_id);
create index if not exists journal_lines_payee_idx on public.journal_lines (account, organization_id, payee_user);

create or replace function public.trg_journal_immutable() returns trigger language plpgsql set search_path = '' as $$
begin raise exception 'journal entries are append-only; post a reversing entry instead'; end $$;
drop trigger if exists journal_entries_immutable on public.journal_entries;
create trigger journal_entries_immutable before update or delete on public.journal_entries for each row execute function public.trg_journal_immutable();
drop trigger if exists journal_lines_immutable on public.journal_lines;
create trigger journal_lines_immutable before update or delete on public.journal_lines for each row execute function public.trg_journal_immutable();

-- Every entry must balance (and have at least two lines) by the end of the transaction that wrote it.
create or replace function public.trg_journal_balanced() returns trigger language plpgsql set search_path = '' as $$
declare s bigint; n integer;
begin
  select coalesce(sum(amount_cents), 0), count(*) into s, n from public.journal_lines where entry_id = new.entry_id;
  if s <> 0 or n < 2 then raise exception 'journal entry % does not balance (sum %, % lines)', new.entry_id, s, n; end if;
  return null;
end $$;
drop trigger if exists journal_balanced on public.journal_lines;
create constraint trigger journal_balanced after insert on public.journal_lines deferrable initially deferred for each row execute function public.trg_journal_balanced();

alter table public.journal_entries enable row level security;
alter table public.journal_lines enable row level security;
drop policy if exists journal_entries_read on public.journal_entries;
create policy journal_entries_read on public.journal_entries for select to authenticated using (public.is_admin());
drop policy if exists journal_lines_read on public.journal_lines;
create policy journal_lines_read on public.journal_lines for select to authenticated
  using (public.is_admin() or (account = 'organizer_payable' and public.can_view_finance(organization_id, payee_user)));
revoke all on public.journal_entries, public.journal_lines from anon, authenticated;
grant select on public.journal_entries, public.journal_lines to authenticated;

-- Posts one balanced entry. lines: [{"account": "...", "amount": 123, "org": uuid?, "user": uuid?}]. Same key twice = no-op.
create or replace function public.post_journal(p_kind text, p_key text, p_refs jsonb, p_lines jsonb, p_memo text default '') returns bigint
language plpgsql security definer set search_path = '' as $$
declare eid bigint; l jsonb;
begin
  insert into public.journal_entries (kind, idempotency_key, event_id, order_id, refund_id, payout_id, dispute_id, fee_policy_id, memo, created_by)
  values (p_kind, p_key, nullif(p_refs->>'event', '')::uuid, nullif(p_refs->>'order', '')::uuid, nullif(p_refs->>'refund', '')::uuid,
          nullif(p_refs->>'payout', '')::uuid, nullif(p_refs->>'dispute', '')::uuid, nullif(p_refs->>'policy', '')::uuid, left(coalesce(p_memo, ''), 300), auth.uid())
  on conflict (idempotency_key) do nothing
  returning id into eid;
  if eid is null then return null; end if;                     -- already posted
  for l in select * from jsonb_array_elements(p_lines) loop
    continue when coalesce((l->>'amount')::bigint, 0) = 0;
    insert into public.journal_lines (entry_id, account, organization_id, payee_user, amount_cents)
    values (eid, l->>'account', nullif(l->>'org', '')::uuid, nullif(l->>'user', '')::uuid, (l->>'amount')::bigint);
  end loop;
  return eid;
end $$;

-- ---------------------------------------------------------------- 3. payment notifications and reconciliation queue
create table if not exists public.payment_notifications (
  id bigint generated always as identity primary key,
  provider text not null check (provider in ('payfast', 'ozow')),
  provider_txn_id text not null check (char_length(provider_txn_id) between 1 and 120),
  reported_status text not null check (char_length(reported_status) between 1 and 40),
  order_ref text not null check (char_length(order_ref) <= 80),
  order_kind text check (order_kind in ('ticket', 'badge')),
  amount_cents bigint,
  currency text,
  outcome text not null default 'received' check (outcome in ('received', 'fulfilled', 'closed', 'ignored', 'amount_mismatch', 'not_confirmed', 'unknown_order', 'error')),
  times_seen integer not null default 1,
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  unique (provider, provider_txn_id, reported_status)
);
create index if not exists payment_notifications_order_idx on public.payment_notifications (order_ref);
alter table public.payment_notifications enable row level security;
drop policy if exists payment_notifications_read on public.payment_notifications;
create policy payment_notifications_read on public.payment_notifications for select to authenticated using (public.is_admin());
revoke all on public.payment_notifications from anon, authenticated;
grant select on public.payment_notifications to authenticated;

create table if not exists public.reconciliation_exceptions (
  id bigint generated always as identity primary key,
  kind text not null check (char_length(kind) between 3 and 60),
  ref_key text not null check (char_length(ref_key) between 1 and 120),
  severity text not null default 'high' check (severity in ('low', 'medium', 'high', 'critical')),
  order_id uuid references public.orders(id) on delete restrict,
  refund_id uuid references public.refunds(id) on delete restrict,
  payout_id uuid references public.payouts(id) on delete restrict,
  detail jsonb not null default '{}'::jsonb,
  status text not null default 'open' check (status in ('open', 'resolved', 'dismissed')),
  resolution text not null default '' check (char_length(resolution) <= 1000),
  resolved_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);
create unique index if not exists reconciliation_exceptions_open_key on public.reconciliation_exceptions (kind, ref_key) where status = 'open';
create index if not exists reconciliation_exceptions_status_idx on public.reconciliation_exceptions (status, created_at desc);
alter table public.reconciliation_exceptions enable row level security;
drop policy if exists recon_read on public.reconciliation_exceptions;
create policy recon_read on public.reconciliation_exceptions for select to authenticated using (public.is_admin());
revoke all on public.reconciliation_exceptions from anon, authenticated;
grant select on public.reconciliation_exceptions to authenticated;

create or replace function public.raise_exception_case(p_kind text, p_ref text, p_severity text, p_detail jsonb, p_order uuid default null, p_refund uuid default null, p_payout uuid default null) returns void
language sql security definer set search_path = '' as $$
  insert into public.reconciliation_exceptions (kind, ref_key, severity, detail, order_id, refund_id, payout_id)
  values (p_kind, p_ref, p_severity, coalesce(p_detail, '{}'::jsonb), p_order, p_refund, p_payout)
  on conflict (kind, ref_key) where status = 'open' do nothing;
$$;

-- Webhook workers (service role) record each verified notification. Returns the row id and whether it was seen before.
create or replace function public.record_payment_notification(p_provider text, p_txn text, p_status text, p_order_ref text, p_amount_cents bigint, p_currency text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r public.payment_notifications;
begin
  insert into public.payment_notifications (provider, provider_txn_id, reported_status, order_ref, amount_cents, currency,
                                            order_kind)
  values (p_provider, left(coalesce(nullif(p_txn, ''), p_order_ref), 120), left(p_status, 40), left(p_order_ref, 80), p_amount_cents, left(p_currency, 3),
          case when exists (select 1 from public.orders where id::text = p_order_ref) then 'ticket' else null end)
  on conflict (provider, provider_txn_id, reported_status) do update set times_seen = payment_notifications.times_seen + 1, last_seen_at = now()
  returning * into r;
  return jsonb_build_object('id', r.id, 'duplicate', r.times_seen > 1, 'outcome', r.outcome);
end $$;
create or replace function public.finish_payment_notification(p_id bigint, p_outcome text) returns void
language plpgsql security definer set search_path = '' as $$
declare r public.payment_notifications;
begin
  update public.payment_notifications set outcome = p_outcome where id = p_id and (outcome = 'received' or p_outcome in ('error', 'amount_mismatch', 'not_confirmed')) returning * into r;
  if found and p_outcome in ('amount_mismatch', 'not_confirmed', 'error') then
    perform public.raise_exception_case('payment_' || p_outcome, r.provider || ':' || r.provider_txn_id, case when p_outcome = 'amount_mismatch' then 'critical' else 'high' end,
      jsonb_build_object('provider', r.provider, 'txn', r.provider_txn_id, 'order_ref', r.order_ref, 'amount_cents', r.amount_cents, 'status', r.reported_status),
      (select id from public.orders where id::text = r.order_ref));
  end if;
end $$;

-- ---------------------------------------------------------------- 4. ticket-sales review, evidence, lineup verification
alter table public.events add column if not exists sales_review text not null default 'not_submitted'
  check (sales_review in ('not_submitted', 'submitted', 'under_review', 'approved', 'rejected', 'suspended'));
alter table public.events add column if not exists sales_review_note text not null default '' check (char_length(sales_review_note) <= 1000);
alter table public.events add column if not exists sales_reviewed_at timestamptz;
create index if not exists events_sales_review_idx on public.events (sales_review) where sales_review in ('submitted', 'under_review', 'suspended');

-- Members may insert events (table-wide grant), so the review state can never be chosen by the creator.
create or replace function public.trg_event_review_insert() returns trigger language plpgsql set search_path = '' as $$
begin
  new.sales_review := 'not_submitted'; new.sales_review_note := ''; new.sales_reviewed_at := null;
  return new;
end $$;
drop trigger if exists event_review_insert on public.events;
create trigger event_review_insert before insert on public.events for each row execute function public.trg_event_review_insert();

create table if not exists public.event_sales_decisions (
  id bigint generated always as identity primary key,
  event_id uuid not null references public.events(id) on delete cascade,
  from_status text not null,
  to_status text not null,
  actor uuid references public.profiles(id) on delete set null,
  reason text not null default '' check (char_length(reason) <= 1000),
  created_at timestamptz not null default now()
);
create index if not exists event_sales_decisions_event_idx on public.event_sales_decisions (event_id, created_at desc);

create table if not exists public.event_evidence (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events(id) on delete cascade,
  kind text not null check (kind in ('organiser_identity', 'business_registration', 'venue_authorisation', 'lineup_confirmation', 'other')),
  note text not null default '' check (char_length(note) <= 1000),
  file_path text check (file_path is null or char_length(file_path) <= 200),
  submitted_by uuid not null references public.profiles(id) on delete restrict,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'expired')),
  review_reason text not null default '' check (char_length(review_reason) <= 500),
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  check (btrim(note) <> '' or file_path is not null),
  check (file_path is null or file_path like submitted_by::text || '/%')
);
create index if not exists event_evidence_event_idx on public.event_evidence (event_id, created_at desc);
create index if not exists event_evidence_file_idx on public.event_evidence (file_path) where file_path is not null;

alter table public.event_sales_decisions enable row level security;
alter table public.event_evidence enable row level security;
drop policy if exists esd_read on public.event_sales_decisions;
create policy esd_read on public.event_sales_decisions for select to authenticated using (public.is_admin() or public.can_manage_event(event_id));
drop policy if exists evidence_read on public.event_evidence;
create policy evidence_read on public.event_evidence for select to authenticated using (public.is_admin() or public.can_manage_event(event_id));
revoke all on public.event_sales_decisions, public.event_evidence from anon, authenticated;
grant select on public.event_sales_decisions, public.event_evidence to authenticated;

create or replace function public.add_event_evidence(p_event uuid, p_kind text, p_note text, p_file_path text default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare new_id uuid;
begin
  if not public.can_manage_event(p_event) then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(*) from public.event_evidence where event_id = p_event) >= 30 then raise exception 'Too much evidence on one event; contact VYBE'; end if;
  insert into public.event_evidence (event_id, kind, note, file_path, submitted_by)
  values (p_event, p_kind, left(coalesce(p_note, ''), 1000), nullif(p_file_path, ''), auth.uid()) returning id into new_id;
  return new_id;
end $$;

create or replace function public.submit_event_for_sales_review(p_event uuid, p_note text default '') returns text
language plpgsql security definer set search_path = '' as $$
declare ev public.events;
begin
  if not public.can_manage_event(p_event) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ev from public.events where id = p_event for update;
  if ev.sales_review not in ('not_submitted', 'rejected') then raise exception 'This event is already %', replace(ev.sales_review, '_', ' '); end if;
  if ev.status <> 'active' then raise exception 'Only active events can open ticket sales'; end if;
  if not exists (select 1 from public.event_evidence where event_id = p_event and status in ('pending', 'approved')) then
    raise exception 'Add at least one piece of evidence (who you are, and that you have the venue) before submitting';
  end if;
  update public.events set sales_review = 'submitted', sales_review_note = left(coalesce(p_note, ''), 1000) where id = p_event;
  insert into public.event_sales_decisions (event_id, from_status, to_status, actor, reason) values (p_event, ev.sales_review, 'submitted', auth.uid(), left(coalesce(p_note, ''), 1000));
  return 'submitted';
end $$;

-- VYBE reviewers: explicit transitions only, a reason for every negative decision, never on their own events.
create or replace function public.admin_review_event_sales(p_event uuid, p_decision text, p_reason text default '') returns text
language plpgsql security definer set search_path = '' as $$
declare ev public.events; ok boolean;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ev from public.events where id = p_event for update;
  if not found then raise exception 'Event not found'; end if;
  if ev.host = auth.uid() or (ev.organization_id is not null and public.org_role(ev.organization_id) is not null) then
    raise exception 'You cannot review an event you host or belong to' using errcode = '42501';
  end if;
  ok := (ev.sales_review, p_decision) in (('submitted', 'under_review'), ('submitted', 'approved'), ('submitted', 'rejected'),
        ('under_review', 'approved'), ('under_review', 'rejected'), ('approved', 'suspended'), ('suspended', 'approved'), ('suspended', 'rejected'));
  if not ok then raise exception 'Cannot move ticket sales from % to %', ev.sales_review, p_decision; end if;
  if p_decision in ('rejected', 'suspended') and coalesce(btrim(p_reason), '') = '' then raise exception 'Give a reason the organiser can act on'; end if;
  update public.events set sales_review = p_decision, sales_reviewed_at = now(),
         sales_review_note = case when p_decision in ('rejected', 'suspended', 'approved') then left(coalesce(p_reason, ''), 1000) else sales_review_note end
   where id = p_event;
  insert into public.event_sales_decisions (event_id, from_status, to_status, actor, reason) values (p_event, ev.sales_review, p_decision, auth.uid(), left(coalesce(p_reason, ''), 1000));
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'event.sales_' || p_decision, 'event', p_event, jsonb_build_object('from', ev.sales_review, 'reason', p_reason));
  perform public.notify(ev.host, 'sales_review', null, 'event', p_event, 'sr:' || p_event || ':' || p_decision || ':' || extract(epoch from now())::bigint);
  return p_decision;
end $$;

create or replace function public.admin_decide_evidence(p_evidence uuid, p_status text, p_reason text default '') returns void
language plpgsql security definer set search_path = '' as $$
declare e public.event_evidence; ev public.events;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('approved', 'rejected', 'expired') then raise exception 'bad status'; end if;
  select * into e from public.event_evidence where id = p_evidence for update;
  if not found then raise exception 'Evidence not found'; end if;
  select * into ev from public.events where id = e.event_id;
  if ev.host = auth.uid() or (ev.organization_id is not null and public.org_role(ev.organization_id) is not null) then raise exception 'You cannot review your own event' using errcode = '42501'; end if;
  if p_status = 'rejected' and coalesce(btrim(p_reason), '') = '' then raise exception 'Give a reason'; end if;
  update public.event_evidence set status = p_status, review_reason = left(coalesce(p_reason, ''), 500), reviewed_by = auth.uid(), reviewed_at = now() where id = p_evidence;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'evidence.' || p_status, 'event_evidence', p_evidence, jsonb_build_object('event', e.event_id));
end $$;

-- Lineup: verification status (organisers cannot set it; editing a confirmed entry marks it CHANGED) and a full history.
alter table public.event_lineup add column if not exists status text not null default 'pending' check (status in ('pending', 'confirmed', 'changed', 'disputed', 'cancelled'));
alter table public.event_lineup add column if not exists status_note text not null default '' check (char_length(status_note) <= 300);
alter table public.event_lineup add column if not exists verified_by uuid references public.profiles(id) on delete set null;
alter table public.event_lineup add column if not exists verified_at timestamptz;
alter table public.event_lineup add column if not exists organization_id uuid references public.organizations(id) on delete set null;   -- the artist's VYBE page, when linked

create table if not exists public.event_lineup_history (
  id bigint generated always as identity primary key,
  lineup_id uuid not null,
  event_id uuid not null,                       -- no foreign key: history must survive (and not block) deleting the event
  op text not null check (op in ('insert', 'update', 'delete', 'status')),
  before jsonb,
  after jsonb,
  actor uuid,
  created_at timestamptz not null default now()
);
create index if not exists event_lineup_history_event_idx on public.event_lineup_history (event_id, created_at desc);
alter table public.event_lineup_history enable row level security;
drop policy if exists lineup_history_read on public.event_lineup_history;
create policy lineup_history_read on public.event_lineup_history for select to authenticated using (public.is_admin() or public.can_manage_event(event_id));
revoke all on public.event_lineup_history from anon, authenticated;
grant select on public.event_lineup_history to authenticated;

create or replace function public.trg_lineup_guard() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if current_setting('vybe.lineup_review', true) is distinct from '1' then new.status := 'pending'; new.verified_by := null; new.verified_at := null; new.status_note := ''; end if;
    insert into public.event_lineup_history (lineup_id, event_id, op, after, actor) values (new.id, new.event_id, 'insert', to_jsonb(new), auth.uid());
    return new;
  elsif tg_op = 'UPDATE' then
    if current_setting('vybe.lineup_review', true) is distinct from '1' then
      new.status := old.status; new.verified_by := old.verified_by; new.verified_at := old.verified_at; new.status_note := old.status_note; new.organization_id := old.organization_id;
      if (new.name, new.role) is distinct from (old.name, old.role) and old.status = 'confirmed' then new.status := 'changed'; new.status_note := 'Changed after confirmation; awaiting review'; end if;
    end if;
    insert into public.event_lineup_history (lineup_id, event_id, op, before, after, actor)
    values (new.id, new.event_id, case when current_setting('vybe.lineup_review', true) = '1' then 'status' else 'update' end, to_jsonb(old), to_jsonb(new), auth.uid());
    return new;
  else
    insert into public.event_lineup_history (lineup_id, event_id, op, before, actor) values (old.id, old.event_id, 'delete', to_jsonb(old), auth.uid());
    return old;
  end if;
end $$;
drop trigger if exists lineup_guard on public.event_lineup;
create trigger lineup_guard before insert or update or delete on public.event_lineup for each row execute function public.trg_lineup_guard();

create or replace function public.admin_set_lineup_status(p_lineup uuid, p_status text, p_note text default '') returns void
language plpgsql security definer set search_path = '' as $$
declare l public.event_lineup;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('pending', 'confirmed', 'changed', 'disputed', 'cancelled') then raise exception 'bad status'; end if;
  if p_status in ('confirmed', 'disputed', 'cancelled') and coalesce(btrim(p_note), '') = '' then raise exception 'Say how this was established (source of confirmation, or the claim)'; end if;
  perform set_config('vybe.lineup_review', '1', true);
  update public.event_lineup set status = p_status, status_note = left(coalesce(p_note, ''), 300), verified_by = auth.uid(), verified_at = now() where id = p_lineup returning * into l;
  perform set_config('vybe.lineup_review', '', true);
  if not found then raise exception 'Lineup entry not found'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'lineup.' || p_status, 'event_lineup', p_lineup, jsonb_build_object('event', l.event_id, 'note', p_note));
end $$;

-- ---------------------------------------------------------------- orders: sales gate, fee policy, snapshot
create or replace function public.create_order(p_event uuid, p_items jsonb, p_provider text, p_idem text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid(); ev public.events; cfg public.platform_config; ord public.orders; pol public.fee_policies; snap jsonb;
  it jsonb; tt public.ticket_types; q integer; subtotal bigint := 0; total_units integer := 0; mine integer;
begin
  if uid is null then raise exception 'Sign in to buy tickets' using errcode = '28000'; end if;
  if exists (select 1 from public.buyer_flags where user_id = uid) then raise exception 'Purchases are disabled for this account. Please contact support.'; end if;
  if p_provider is null or p_provider not in ('payfast','ozow') then raise exception 'Choose PayFast or Ozow'; end if;
  if p_idem is null or char_length(p_idem) < 8 then raise exception 'Missing idempotency key'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 10 then raise exception 'Choose at least one ticket'; end if;
  if (select count(distinct e->>'ticket_type_id') from jsonb_array_elements(p_items) e) <> jsonb_array_length(p_items) then raise exception 'Each ticket type can appear once per order'; end if;

  select * into ord from public.orders where buyer = uid and idempotency_key = p_idem;
  if found then return jsonb_build_object('id', ord.id, 'status', ord.status, 'total_cents', ord.total_cents, 'fee_cents', ord.fee_cents, 'subtotal_cents', ord.subtotal_cents, 'expires_at', ord.expires_at); end if;

  select * into cfg from public.platform_config where id;
  select * into ev from public.events e where e.id = p_event;
  if not found or ev.status <> 'active' or not public.can_view_event(ev) then raise exception 'This event is not available'; end if;
  if coalesce(ev.ends_at, ev.starts_at + interval '6 hours') < now() then raise exception 'This event has ended'; end if;

  if (select count(*) from public.orders where buyer = uid and created_at > now() - interval '10 minutes') >= 6 then raise exception 'Too many attempts. Please wait a few minutes.'; end if;
  if (select count(*) from public.orders where buyer = uid and created_at > now() - interval '24 hours') >= 30 then raise exception 'Daily purchase limit reached.'; end if;
  if (select count(*) from public.orders where buyer = uid and status = 'pending' and expires_at > now()) >= 3 then raise exception 'Finish or cancel your pending orders first.'; end if;

  -- Lock ticket types in a fixed order (by id) so two orders for the same types can never deadlock.
  for it in select e from jsonb_array_elements(p_items) e order by e->>'ticket_type_id' loop
    q := (it->>'qty')::integer;
    select * into tt from public.ticket_types where id = (it->>'ticket_type_id')::uuid and event_id = p_event for update;
    if not found then raise exception 'Unknown ticket type'; end if;
    if tt.status <> 'active' then raise exception '% is not on sale', tt.name; end if;
    if tt.sales_start is not null and tt.sales_start > now() then raise exception '% is not on sale yet', tt.name; end if;
    if tt.sales_end is not null and tt.sales_end < now() then raise exception 'Sales for % have closed', tt.name; end if;
    if q is null or q < 1 or q > tt.max_per_order then raise exception 'You can buy 1 to % of %', tt.max_per_order, tt.name; end if;
    if public.ticket_units_taken(tt.id) + q > tt.quantity_total then raise exception '% is sold out', tt.name; end if;
    subtotal := subtotal + tt.price_cents::bigint * q;
    total_units := total_units + q * tt.group_size;
  end loop;
  if total_units > cfg.max_tickets_per_order then raise exception 'You can buy up to % tickets per order', cfg.max_tickets_per_order; end if;
  select count(*) into mine from public.tickets where owner = uid and event_id = p_event and status in ('valid','used');
  if mine + total_units > 20 then raise exception 'Ticket limit per person reached for this event'; end if;

  -- Paid sales need VYBE's review of the event; free tickets do not.
  if subtotal > 0 and cfg.require_sales_review and ev.sales_review <> 'approved' then
    raise exception 'Ticket sales for this event open once VYBE has reviewed it';
  end if;

  pol := public.fee_policy_for(p_event);
  if subtotal > 0 and pol.id is null then raise exception 'Ticket sales are not configured yet'; end if;
  snap := public.price_order(pol, subtotal, total_units, cfg.vat_registered, cfg.vat_rate_bps);
  if (snap->>'total_cents')::bigint > 0 and (snap->>'total_cents')::bigint < 500 then raise exception 'The minimum card/EFT payment is R5.00'; end if;

  insert into public.orders (buyer, event_id, provider, subtotal_cents, fee_cents, fee_vat_cents, total_cents, idempotency_key, expires_at,
                             fee_policy_id, pricing, commission_cents, commission_vat_cents, organizer_net_cents)
  values (uid, p_event, case when subtotal = 0 then 'free' else p_provider end, subtotal, (snap->>'buyer_fee_cents')::bigint, (snap->>'buyer_fee_vat_cents')::bigint,
          (snap->>'total_cents')::bigint, p_idem, now() + make_interval(mins => cfg.hold_minutes),
          pol.id, snap, (snap->>'commission_cents')::bigint, (snap->>'commission_vat_cents')::bigint, (snap->>'organizer_net_cents')::bigint)
  returning * into ord;
  for it in select * from jsonb_array_elements(p_items) loop
    insert into public.order_items (order_id, ticket_type_id, qty, unit_price_cents)
    select ord.id, t.id, (it->>'qty')::integer, t.price_cents from public.ticket_types t where t.id = (it->>'ticket_type_id')::uuid;
  end loop;

  if ord.total_cents = 0 then perform public.issue_tickets(ord.id, 'free', null); select * into ord from public.orders where id = ord.id; end if;
  return jsonb_build_object('id', ord.id, 'status', ord.status, 'total_cents', ord.total_cents, 'fee_cents', ord.fee_cents, 'subtotal_cents', ord.subtotal_cents, 'expires_at', ord.expires_at);
end $$;

-- Sale journal for a paid order (idempotent by key).
create or replace function public.post_sale_journal(o public.orders) returns void
language plpgsql security definer set search_path = '' as $$
declare pay record; net bigint := coalesce(o.organizer_net_cents, o.subtotal_cents);
begin
  if o.total_cents <= 0 then return; end if;
  select * into pay from public.event_payee(o.event_id);
  perform public.post_journal('sale', 'sale:' || o.id, jsonb_build_object('event', o.event_id, 'order', o.id, 'policy', o.fee_policy_id), jsonb_build_array(
    jsonb_build_object('account', 'platform_cash', 'amount', o.total_cents),
    jsonb_build_object('account', 'organizer_payable', 'amount', -net, 'org', pay.org, 'user', pay.usr),
    jsonb_build_object('account', 'commission_revenue', 'amount', -(o.commission_cents - o.commission_vat_cents)),
    jsonb_build_object('account', 'buyer_fee_revenue', 'amount', -(o.fee_cents - o.fee_vat_cents)),
    jsonb_build_object('account', 'vat_payable', 'amount', -(o.commission_vat_cents + o.fee_vat_cents))), 'Ticket sale');
end $$;

create or replace function public.issue_tickets(p_order uuid, p_provider text, p_ref text, p_method text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare o public.orders; r record; n integer; k integer; cfg public.platform_config; pay record; lines jsonb; bname text; ev public.events; rid uuid;
begin
  select * into o from public.orders where id = p_order for update;
  if not found then raise exception 'order not found'; end if;
  if o.status in ('paid','partially_refunded','refunded','disputed') then return; end if;
  if o.status = 'failed' and exists (select 1 from public.refunds where order_id = o.id and kind = 'oversold') then return; end if;   -- already handled
  if o.status not in ('pending','expired','failed','cancelled') then raise exception 'order is %', o.status; end if;
  -- Money arrived for an order whose hold lapsed (or that was closed) and the stock is gone: never drop it. The buyer is owed a
  -- full refund, the money is held as refunds_payable, and a person is told.
  if o.status <> 'pending' or o.expires_at < now() then        -- a lapsed hold no longer reserves stock: re-check it
    for r in select oi.ticket_type_id, oi.qty, tt.quantity_total from public.order_items oi join public.ticket_types tt on tt.id = oi.ticket_type_id where oi.order_id = o.id loop
      if public.ticket_units_taken(r.ticket_type_id) + r.qty > r.quantity_total then
        update public.orders set status = 'failed', provider = p_provider, provider_ref = coalesce(p_ref, provider_ref), payment_method = coalesce(p_method, payment_method) where id = o.id;
        insert into public.refunds (order_id, requested_by, kind, status, ticket_ids, ticket_amount_cents, fee_amount_cents, reason, decided_at)
        values (o.id, o.buyer, 'oversold', 'approved', '{}', o.subtotal_cents, o.fee_cents, 'Paid after the hold lapsed and the tickets had sold out', now())
        returning id into rid;
        perform public.post_journal('oversold_hold', 'oversold:' || o.id, jsonb_build_object('event', o.event_id, 'order', o.id, 'refund', rid), jsonb_build_array(
          jsonb_build_object('account', 'platform_cash', 'amount', o.total_cents), jsonb_build_object('account', 'refunds_payable', 'amount', -o.total_cents)), 'Paid after expiry; sold out; refund owed');
        perform public.raise_exception_case('paid_after_expiry_soldout', o.id::text, 'high', jsonb_build_object('provider', p_provider, 'ref', p_ref, 'total_cents', o.total_cents), o.id, rid);
        insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (null, 'order.paid_after_expiry_soldout', 'order', o.id, jsonb_build_object('provider', p_provider, 'ref', p_ref, 'refund', rid));
        perform public.notify(o.buyer, 'refund_update', null, 'order', o.id, 'oversold:' || o.id);
        return;
      end if;
    end loop;
  end if;
  for r in select oi.qty, oi.ticket_type_id, tt.group_size from public.order_items oi join public.ticket_types tt on tt.id = oi.ticket_type_id where oi.order_id = o.id loop
    n := r.qty * r.group_size;
    for k in 1..n loop
      -- 80 random bits from the CSPRNG, uppercase hex: not guessable, not sequential, carries no personal data.
      insert into public.tickets (order_id, event_id, ticket_type_id, owner, code)
      values (o.id, o.event_id, r.ticket_type_id, o.buyer, upper(substr(md5(gen_random_uuid()::text || gen_random_uuid()::text), 1, 20)));
    end loop;
  end loop;
  update public.orders set status = 'paid', provider = p_provider, provider_ref = coalesce(p_ref, provider_ref), payment_method = coalesce(p_method, payment_method), paid_at = now()
   where id = o.id returning * into o;

  select * into pay from public.event_payee(o.event_id);
  if o.subtotal_cents > 0 then
    insert into public.ledger_entries (event_id, organization_id, payee_user, order_id, kind, amount_cents, note)
    values (o.event_id, pay.org, pay.usr, o.id, 'sale', coalesce(o.organizer_net_cents, o.subtotal_cents), 'Ticket sales (after commission)');
  end if;
  perform public.post_sale_journal(o);

  select * into ev from public.events where id = o.event_id;
  if o.total_cents > 0 and ev.sales_review <> 'approved' then
    perform public.raise_exception_case('paid_while_not_approved', o.id::text, 'medium', jsonb_build_object('sales_review', ev.sales_review), o.id);
  end if;

  select * into cfg from public.platform_config where id;
  select coalesce(nullif(display_name, ''), username) into bname from public.profiles where id = o.buyer;
  select coalesce(jsonb_agg(jsonb_build_object('name', tt.name, 'qty', oi.qty, 'unit_price_cents', oi.unit_price_cents, 'line_total_cents', oi.qty * oi.unit_price_cents, 'tickets', oi.qty * tt.group_size)), '[]'::jsonb)
    into lines from public.order_items oi join public.ticket_types tt on tt.id = oi.ticket_type_id where oi.order_id = o.id;
  insert into public.invoices (order_id, buyer, number, kind, legal_name, vat_number, buyer_name, lines, subtotal_cents, fee_cents, fee_vat_cents, total_cents)
  values (o.id, o.buyer, 'VYB-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.invoice_seq')::text, 6, '0'),
          case when cfg.vat_registered and cfg.vat_number is not null then 'tax_invoice' else 'receipt' end,
          cfg.legal_name, case when cfg.vat_registered then cfg.vat_number end, coalesce(bname, ''), lines, o.subtotal_cents, o.fee_cents, o.fee_vat_cents, o.total_cents)
  on conflict (order_id) do nothing;

  perform public.notify(o.buyer, 'ticket_order', null, 'order', o.id, 'paid:' || o.id);
  begin
    insert into public.event_rsvps (event_id, user_id, status) values (o.event_id, o.buyer, 'going')
    on conflict (event_id, user_id) do update set status = 'going';
  exception when others then null;
  end;
end $$;

-- Closing a payment that failed: notify the buyer once.
create or replace function public.close_order(p_order uuid, p_status text) returns void
language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
  if p_status not in ('failed','cancelled') then raise exception 'bad status'; end if;
  update public.orders set status = p_status where id = p_order and status = 'pending' returning * into o;
  if found and p_status = 'failed' then perform public.notify(o.buyer, 'ticket_order', null, 'order', o.id, 'failed:' || o.id); end if;
end $$;

-- ---------------------------------------------------------------- refunds: commission reversal, oversold refunds, locking
alter table public.refunds drop constraint if exists refunds_kind_check;
alter table public.refunds add constraint refunds_kind_check check (kind in ('buyer_request', 'organizer', 'event_cancelled', 'admin', 'oversold'));

-- How a refund splits between the organiser and VYBE, under the order's own terms (commission is returned in proportion).
create or replace function public.refund_split(o public.orders, p_ticket_amount bigint, p_fee_amount bigint) returns jsonb
language sql stable set search_path = '' as $$
  with c as (
    select case when o.subtotal_cents > 0 then div(p_ticket_amount::numeric * o.commission_cents + div(o.subtotal_cents, 2), o.subtotal_cents)::bigint else 0 end as comm,
           case when o.subtotal_cents > 0 then div(p_ticket_amount::numeric * o.commission_vat_cents + div(o.subtotal_cents, 2), o.subtotal_cents)::bigint else 0 end as comm_vat,
           case when o.fee_cents > 0 then div(p_fee_amount::numeric * o.fee_vat_cents + div(o.fee_cents, 2), o.fee_cents)::bigint else 0 end as fee_vat)
  select jsonb_build_object('organizer', p_ticket_amount - least(comm, p_ticket_amount), 'commission', least(comm, p_ticket_amount), 'commission_vat', least(comm_vat, least(comm, p_ticket_amount)),
                            'fee', p_fee_amount, 'fee_vat', least(fee_vat, p_fee_amount)) from c;
$$;

create or replace function public.request_refund(p_order uuid, p_reason text, p_tickets uuid[] default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders; ev public.events; cfg public.platform_config; ids uuid[]; amt bigint := 0; r public.refunds; st text; bad integer; is_full boolean;
begin
  select * into o from public.orders where id = p_order for update;                          -- one refund decision at a time per order
  if not found or o.buyer <> auth.uid() then raise exception 'Order not found'; end if;
  if o.status not in ('paid','partially_refunded') then raise exception 'This order cannot be refunded'; end if;
  if exists (select 1 from public.refunds where order_id = o.id and status in ('requested','approved','processing','manual_required')) then raise exception 'A refund for this order is already in progress'; end if;
  select * into ev from public.events where id = o.event_id;
  select * into cfg from public.platform_config where id;
  if p_tickets is null or cardinality(p_tickets) = 0 then
    select array_agg(id) into ids from public.tickets where order_id = o.id and status = 'valid';
  else
    ids := p_tickets;
    select count(*) into bad from unnest(ids) x where not exists (select 1 from public.tickets t where t.id = x and t.order_id = o.id and t.status = 'valid');
    if bad > 0 then raise exception 'Some tickets cannot be refunded (already used, refunded or not yours)'; end if;
  end if;
  if ids is null or cardinality(ids) = 0 then raise exception 'There is nothing left to refund on this order'; end if;
  select coalesce(sum(case when tt.group_size > 1 then tt.price_cents / tt.group_size else tt.price_cents end), 0) into amt
    from public.tickets t join public.ticket_types tt on tt.id = t.ticket_type_id where t.id = any (ids);
  amt := least(amt, o.subtotal_cents - least(o.refunded_cents, o.subtotal_cents));
  if amt <= 0 and o.subtotal_cents > 0 then raise exception 'There is nothing left to refund on this order'; end if;
  is_full := not exists (select 1 from public.tickets t where t.order_id = o.id and t.status = 'valid' and t.id <> all (ids)) and o.refunded_cents = 0 and not exists (select 1 from public.tickets t where t.order_id = o.id and t.status <> 'valid');
  st := case when now() <= ev.starts_at - make_interval(hours => cfg.buyer_refund_hours) then 'approved' else 'requested' end;
  insert into public.refunds (order_id, requested_by, kind, status, ticket_ids, ticket_amount_cents, fee_amount_cents, reason, decided_at)
  values (o.id, auth.uid(), 'buyer_request', st, ids, amt, 0, left(coalesce(p_reason, ''), 500), case when st = 'approved' then now() end)
  returning * into r;
  return jsonb_build_object('id', r.id, 'status', r.status, 'ticket_amount_cents', r.ticket_amount_cents, 'full', is_full);
end $$;

create or replace function public.refund_finish(p_refund uuid, p_status text, p_provider text, p_ref text, p_error text default null) returns void
language plpgsql security definer set search_path = '' as $$
declare r public.refunds; o public.orders; pay record; total bigint; sp jsonb;
begin
  if p_status not in ('succeeded','failed','manual_required') then raise exception 'bad status'; end if;
  select * into r from public.refunds where id = p_refund for update;
  if not found then raise exception 'Refund not found'; end if;
  if r.status not in ('processing','manual_required') then raise exception 'Refund is %', r.status; end if;
  if p_status <> 'succeeded' then
    update public.refunds set status = p_status, provider = p_provider, error = left(p_error, 500) where id = p_refund;
    if p_status = 'failed' then perform public.raise_exception_case('refund_failed', r.id::text, 'high', jsonb_build_object('error', left(p_error, 300)), r.order_id, r.id); end if;
    return;
  end if;
  select * into o from public.orders where id = r.order_id for update;
  total := r.ticket_amount_cents + r.fee_amount_cents;
  if o.refunded_cents + total > o.total_cents then
    perform public.raise_exception_case('refund_exceeds_paid', r.id::text, 'critical', jsonb_build_object('refunded', o.refunded_cents, 'this', total, 'paid', o.total_cents), o.id, r.id);
    raise exception 'Refund would exceed what was paid';
  end if;
  update public.refunds set status = 'succeeded', provider = p_provider, provider_ref = p_ref, error = null, processed_at = now() where id = p_refund;
  update public.tickets set status = 'refunded' where id = any (r.ticket_ids) and status = 'valid';
  update public.orders set refunded_cents = refunded_cents + total,
         status = case when r.kind = 'oversold' then 'refunded'
                       when refunded_cents + total >= total_cents or not exists (select 1 from public.tickets t where t.order_id = orders.id and t.status in ('valid','used')) then 'refunded' else 'partially_refunded' end
   where id = o.id;
  if r.kind = 'oversold' then
    perform public.post_journal('refund', 'refund:' || r.id, jsonb_build_object('event', o.event_id, 'order', o.id, 'refund', r.id), jsonb_build_array(
      jsonb_build_object('account', 'refunds_payable', 'amount', total), jsonb_build_object('account', 'platform_cash', 'amount', -total)), 'Refund of an oversold payment');
  else
    select * into pay from public.event_payee(o.event_id);
    sp := public.refund_split(o, r.ticket_amount_cents, r.fee_amount_cents);
    if (sp->>'organizer')::bigint > 0 then
      insert into public.ledger_entries (event_id, organization_id, payee_user, order_id, refund_id, kind, amount_cents, note)
      values (o.event_id, pay.org, pay.usr, o.id, r.id, 'refund', -(sp->>'organizer')::bigint, 'Refund to buyer');
    end if;
    perform public.post_journal('refund', 'refund:' || r.id, jsonb_build_object('event', o.event_id, 'order', o.id, 'refund', r.id, 'policy', o.fee_policy_id), jsonb_build_array(
      jsonb_build_object('account', 'organizer_payable', 'amount', (sp->>'organizer')::bigint, 'org', pay.org, 'user', pay.usr),
      jsonb_build_object('account', 'commission_revenue', 'amount', (sp->>'commission')::bigint - (sp->>'commission_vat')::bigint),
      jsonb_build_object('account', 'buyer_fee_revenue', 'amount', (sp->>'fee')::bigint - (sp->>'fee_vat')::bigint),
      jsonb_build_object('account', 'vat_payable', 'amount', (sp->>'commission_vat')::bigint + (sp->>'fee_vat')::bigint),
      jsonb_build_object('account', 'platform_cash', 'amount', -total)), 'Refund to buyer');
  end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'refund.succeeded', 'refund', r.id, jsonb_build_object('order', o.id, 'total_cents', total, 'provider', p_provider));
  perform public.notify(o.buyer, 'refund_update', null, 'order', o.id, 'refund:' || r.id || ':succeeded');
end $$;

-- Event cancellation: stop sales, keep history, queue a full refund (fee included) for every paid order, hold payouts.
create or replace function public.cancel_event_with_refunds(p_event uuid) returns integer
language plpgsql security definer set search_path = '' as $$
declare o record; n integer := 0; ev public.events;
begin
  if not (public.is_admin() or public.can_manage_event(p_event)) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ev from public.events where id = p_event for update;
  update public.events set status = 'cancelled' where id = p_event;
  update public.ticket_types set status = 'paused' where event_id = p_event;
  update public.live_streams set status = 'cancelled' where event_id = p_event and status = 'scheduled';
  insert into public.event_sales_decisions (event_id, from_status, to_status, actor, reason) values (p_event, ev.sales_review, ev.sales_review, auth.uid(), 'Event cancelled');
  for o in select * from public.orders where event_id = p_event and status in ('paid','partially_refunded') order by created_at loop
    continue when exists (select 1 from public.refunds where order_id = o.id and status in ('requested','approved','processing','manual_required'));
    insert into public.refunds (order_id, requested_by, kind, status, ticket_ids, ticket_amount_cents, fee_amount_cents, reason, decided_by, decided_at)
    select o.id, auth.uid(), 'event_cancelled', 'approved', coalesce(array_agg(t.id), '{}'), greatest(0, o.subtotal_cents - least(o.refunded_cents, o.subtotal_cents)),
           case when o.refunded_cents = 0 then o.fee_cents else 0 end, 'Event cancelled by the organizer', auth.uid(), now()
      from public.tickets t where t.order_id = o.id and t.status = 'valid';
    perform public.notify(o.buyer, 'refund_update', null, 'order', o.id, 'cancelled:' || o.id);
    n := n + 1;
  end loop;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'event.cancelled_with_refunds', 'event', p_event, jsonb_build_object('orders', n));
  return n;
end $$;

-- ---------------------------------------------------------------- chargebacks: organiser bears up to their net, VYBE the rest
create or replace function public.resolve_dispute(p_dispute uuid, p_outcome text, p_evidence text default '') returns void
language plpgsql security definer set search_path = '' as $$
declare d public.disputes; o public.orders; pay record; org_part bigint;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_outcome not in ('won','lost') then raise exception 'Outcome must be won or lost'; end if;
  select * into d from public.disputes where id = p_dispute for update;
  if not found or d.status <> 'open' then raise exception 'Dispute is not open'; end if;
  select * into o from public.orders where id = d.order_id for update;
  update public.disputes set status = p_outcome, evidence = left(coalesce(p_evidence, evidence), 4000), resolved_at = now() where id = d.id;
  if p_outcome = 'won' then
    update public.tickets set status = 'valid', void_reason = null where order_id = o.id and void_reason = 'dispute';
    update public.orders set status = case when refunded_cents > 0 then 'partially_refunded' else 'paid' end where id = o.id;
  else
    select * into pay from public.event_payee(o.event_id);
    org_part := least(d.amount_cents, greatest(0, coalesce(o.organizer_net_cents, o.subtotal_cents) - (select coalesce(sum(-amount_cents), 0) from public.ledger_entries where order_id = o.id and kind = 'refund')));
    if org_part > 0 then
      insert into public.ledger_entries (event_id, organization_id, payee_user, order_id, dispute_id, kind, amount_cents, note)
      values (o.event_id, pay.org, pay.usr, o.id, d.id, 'chargeback', -org_part, 'Chargeback lost');
    end if;
    perform public.post_journal('chargeback', 'chargeback:' || d.id, jsonb_build_object('event', o.event_id, 'order', o.id, 'dispute', d.id), jsonb_build_array(
      jsonb_build_object('account', 'organizer_payable', 'amount', org_part, 'org', pay.org, 'user', pay.usr),
      jsonb_build_object('account', 'chargeback_losses', 'amount', d.amount_cents - org_part),
      jsonb_build_object('account', 'platform_cash', 'amount', -d.amount_cents)), 'Chargeback lost');
    update public.orders set status = 'refunded', refunded_cents = o.total_cents where id = o.id;
    update public.tickets set status = 'void', void_reason = 'chargeback' where order_id = o.id and status <> 'used';
    insert into public.buyer_flags (user_id, reason) values (o.buyer, 'Lost chargeback on order ' || o.id) on conflict do nothing;
  end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'dispute.' || p_outcome, 'dispute', d.id, jsonb_build_object('order', o.id));
end $$;

-- ---------------------------------------------------------------- 5. admission
create table if not exists public.event_staff (
  event_id uuid not null references public.events(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'scanner' check (role in ('scanner')),
  added_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (event_id, user_id)
);
alter table public.event_staff enable row level security;
drop policy if exists event_staff_read on public.event_staff;
create policy event_staff_read on public.event_staff for select to authenticated using (user_id = (select auth.uid()) or public.can_manage_event(event_id) or public.is_admin());
drop policy if exists event_staff_ins on public.event_staff;
create policy event_staff_ins on public.event_staff for insert to authenticated with check (public.can_manage_event(event_id) and added_by = (select auth.uid()));
drop policy if exists event_staff_del on public.event_staff;
create policy event_staff_del on public.event_staff for delete to authenticated using (public.can_manage_event(event_id) or user_id = (select auth.uid()));
revoke all on public.event_staff from anon, authenticated;
grant select, delete on public.event_staff to authenticated;
grant insert (event_id, user_id, role, added_by) on public.event_staff to authenticated;

create or replace function public.can_scan_event(eid uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.can_manage_event(eid) or exists (select 1 from public.event_staff s where s.event_id = eid and s.user_id = auth.uid());
$$;

create table if not exists public.ticket_scans (
  id bigint generated always as identity primary key,
  event_id uuid references public.events(id) on delete cascade,
  ticket_id uuid references public.tickets(id) on delete set null,
  scanner uuid references public.profiles(id) on delete set null,
  result text not null check (result in ('ok', 'already_used', 'void', 'refunded', 'wrong_event', 'invalid', 'forbidden', 'event_cancelled', 'not_paid', 'rate_limited')),
  created_at timestamptz not null default now()
);
create index if not exists ticket_scans_event_idx on public.ticket_scans (event_id, created_at desc);
create index if not exists ticket_scans_scanner_idx on public.ticket_scans (scanner, created_at desc);
alter table public.ticket_scans enable row level security;
drop policy if exists ticket_scans_read on public.ticket_scans;
create policy ticket_scans_read on public.ticket_scans for select to authenticated using (public.is_admin() or (event_id is not null and public.can_manage_event(event_id)));
revoke all on public.ticket_scans from anon, authenticated;
grant select on public.ticket_scans to authenticated;

-- Atomic, single-use redemption bound to one event. Every attempt is recorded; bursts of bad codes are throttled.
create or replace function public.admit_ticket(p_event uuid, p_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare t public.tickets; tt public.ticket_types; o public.orders; ev public.events; holder text; c text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')); res text;
begin
  if auth.uid() is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if c like 'VYBE1%' then c := substr(c, 6); end if;
  select * into ev from public.events where id = p_event;
  if not found or not public.can_scan_event(p_event) then
    insert into public.ticket_scans (event_id, scanner, result) values (case when found then p_event end, auth.uid(), 'forbidden');
    return jsonb_build_object('result', 'forbidden');
  end if;
  if (select count(*) from public.ticket_scans where scanner = auth.uid() and result in ('invalid', 'wrong_event') and created_at > now() - interval '5 minutes') >= 40 then
    insert into public.ticket_scans (event_id, scanner, result) values (p_event, auth.uid(), 'rate_limited');
    return jsonb_build_object('result', 'rate_limited');
  end if;
  select * into t from public.tickets where code = c for update;
  if not found then
    insert into public.ticket_scans (event_id, scanner, result) values (p_event, auth.uid(), 'invalid');
    return jsonb_build_object('result', 'invalid');
  end if;
  if t.event_id <> p_event then
    insert into public.ticket_scans (event_id, ticket_id, scanner, result) values (p_event, t.id, auth.uid(), 'wrong_event');
    return jsonb_build_object('result', 'wrong_event');
  end if;
  select * into tt from public.ticket_types where id = t.ticket_type_id;
  select * into o from public.orders where id = t.order_id;
  select coalesce(nullif(display_name, ''), username) into holder from public.profiles where id = t.owner;
  res := case when ev.status = 'cancelled' then 'event_cancelled'
              when t.status = 'used' then 'already_used'
              when t.status = 'refunded' then 'refunded'
              when t.status = 'void' then 'void'
              when o.status not in ('paid', 'partially_refunded') then 'not_paid'
              else 'ok' end;
  if res = 'ok' then update public.tickets set status = 'used', used_at = now(), used_by = auth.uid() where id = t.id; end if;
  insert into public.ticket_scans (event_id, ticket_id, scanner, result) values (p_event, t.id, auth.uid(), res);
  return jsonb_build_object('result', res, 'ticket_type', tt.name, 'holder', holder, 'used_at', case when res = 'already_used' then t.used_at end);
end $$;

-- The older code-only door check stays for existing screens, but now uses the same rules (bound to the ticket's own event).
create or replace function public.check_in_ticket(p_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare eid uuid; c text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')); r jsonb;
begin
  if c like 'VYBE1%' then c := substr(c, 6); end if;
  select event_id into eid from public.tickets where code = c;
  if eid is null then
    insert into public.ticket_scans (scanner, result) values (auth.uid(), 'invalid');
    return jsonb_build_object('result', 'invalid');
  end if;
  r := public.admit_ticket(eid, c);
  return case when r->>'result' = 'already_used' then r || jsonb_build_object('result', 'used') else r end;
end $$;

-- Ticket codes are the door credential: only the holder reads theirs (organisers and scanners never see codes).
revoke select on public.tickets from authenticated;
grant select (id, order_id, event_id, ticket_type_id, owner, status, transfers, used_at, used_by, created_at, void_reason) on public.tickets to authenticated;
create or replace function public.my_ticket_code(p_ticket uuid) returns text
language sql stable security definer set search_path = '' as $$
  select t.code from public.tickets t where t.id = p_ticket and t.owner = auth.uid() and t.status = 'valid';
$$;

-- ---------------------------------------------------------------- 6. payouts
-- Money already promised back to buyers (open refunds, organiser's share) cannot be withdrawn.
create or replace function public.payout_balance(p_org uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare cfg public.platform_config; u uuid := case when p_org is null then auth.uid() end;
        gross bigint; settled bigint; reductions bigint; paid bigint; pending bigint; disputed bigint; committed bigint;
begin
  if not public.can_view_finance(p_org, u) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into cfg from public.platform_config where id;
  select coalesce(sum(l.amount_cents), 0) into gross from public.ledger_entries l where l.kind = 'sale' and l.organization_id is not distinct from p_org and l.payee_user is not distinct from u;
  select coalesce(sum(l.amount_cents), 0) into settled from public.ledger_entries l join public.events e on e.id = l.event_id
   where l.kind = 'sale' and l.organization_id is not distinct from p_org and l.payee_user is not distinct from u
     and e.status <> 'cancelled' and coalesce(e.ends_at, e.starts_at + interval '6 hours') + make_interval(days => cfg.settlement_hold_days) <= now();
  select coalesce(sum(l.amount_cents), 0) into reductions from public.ledger_entries l where l.kind in ('refund','chargeback','adjustment') and l.organization_id is not distinct from p_org and l.payee_user is not distinct from u;
  select coalesce(sum(-l.amount_cents), 0) into paid from public.ledger_entries l where l.kind = 'payout' and l.organization_id is not distinct from p_org and l.payee_user is not distinct from u;
  select coalesce(sum(p.amount_cents), 0) into pending from public.payouts p where p.status in ('requested','approved') and p.organization_id is not distinct from p_org and p.user_id is not distinct from u;
  select coalesce(sum(d.amount_cents), 0) into disputed from public.disputes d join public.orders o on o.id = d.order_id join public.events e on e.id = o.event_id
   where d.status = 'open' and e.organization_id is not distinct from p_org and (p_org is not null or e.host = u);
  select coalesce(sum((public.refund_split(o, r.ticket_amount_cents, 0)->>'organizer')::bigint), 0) into committed
    from public.refunds r join public.orders o on o.id = r.order_id join public.events e on e.id = o.event_id
   where r.kind <> 'oversold' and r.status in ('requested','approved','processing','manual_required')
     and e.organization_id is not distinct from p_org and (p_org is not null or (e.organization_id is null and e.host = u));
  return jsonb_build_object('gross_sales_cents', gross, 'settled_sales_cents', settled, 'refunds_and_chargebacks_cents', -reductions, 'paid_out_cents', paid,
    'pending_payout_cents', pending, 'open_disputes_cents', disputed, 'committed_refunds_cents', committed, 'balance_cents', gross + reductions - paid,
    'available_cents', greatest(0, settled + reductions - paid - pending - disputed - committed), 'min_payout_cents', cfg.payout_min_cents, 'hold_days', cfg.settlement_hold_days);
end $$;

create or replace function public.request_payout(p_org uuid default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare bal jsonb; acct public.payout_accounts; new_id uuid; u uuid := case when p_org is null then auth.uid() end; amt bigint; cfg public.platform_config;
begin
  if not public.can_view_finance(p_org, u) or (p_org is not null and public.org_role(p_org) not in ('owner','admin') and not public.is_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('payout:' || coalesce(p_org::text, u::text), 0));   -- one request at a time per payee
  select * into cfg from public.platform_config where id;
  select * into acct from public.payout_accounts where organization_id is not distinct from p_org and user_id is not distinct from u;
  if not found or acct.status <> 'verified' then raise exception 'Add and verify a payout account first'; end if;
  if acct.updated_at > now() - make_interval(hours => cfg.payout_account_cooloff_hours) then
    raise exception 'Payout details changed recently. For your security, payouts resume % hours after a change.', cfg.payout_account_cooloff_hours;
  end if;
  if exists (select 1 from public.payouts where status in ('requested','approved') and organization_id is not distinct from p_org and user_id is not distinct from u) then raise exception 'You already have a payout in progress'; end if;
  bal := public.payout_balance(p_org); amt := (bal->>'available_cents')::bigint;
  if amt < (bal->>'min_payout_cents')::bigint or amt <= 0 then raise exception 'Available balance is below the minimum payout'; end if;
  insert into public.payouts (organization_id, user_id, amount_cents, requested_by) values (p_org, u, amt, auth.uid()) returning payouts.id into new_id;
  perform public.raise_exception_case('payout_awaiting_approval', new_id::text, 'low', jsonb_build_object('amount_cents', amt), null, null, new_id);
  return new_id;
end $$;

create or replace function public.admin_decide_payout(p_payout uuid, p_approve boolean, p_note text default '') returns void
language plpgsql security definer set search_path = '' as $$
declare p public.payouts;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into p from public.payouts where id = p_payout for update;
  if not found or p.status <> 'requested' then raise exception 'Payout is not awaiting a decision'; end if;
  if p.requested_by = auth.uid() then raise exception 'You cannot approve a payout you requested' using errcode = '42501'; end if;
  if not p_approve and coalesce(btrim(p_note), '') = '' then raise exception 'Give a reason for rejecting'; end if;
  update public.payouts set status = case when p_approve then 'approved' else 'rejected' end, decided_by = auth.uid(), decided_at = now(), note = left(p_note, 500) where id = p_payout;
  update public.reconciliation_exceptions set status = 'resolved', resolved_by = auth.uid(), resolved_at = now(), resolution = case when p_approve then 'Approved' else 'Rejected' end
   where kind = 'payout_awaiting_approval' and ref_key = p_payout::text and status = 'open';
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), case when p_approve then 'payout.approved' else 'payout.rejected' end, 'payout', p_payout, jsonb_build_object('note', p_note));
end $$;

-- Records a bank transfer someone has made. Above the dual-control limit the person confirming must not be the approver.
create or replace function public.admin_mark_payout_paid(p_payout uuid, p_reference text) returns void
language plpgsql security definer set search_path = '' as $$
declare p public.payouts; cfg public.platform_config; bal jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_reference)), 0) < 4 then raise exception 'Enter the bank transfer reference'; end if;
  select * into cfg from public.platform_config where id;
  select * into p from public.payouts where id = p_payout for update;
  if not found or p.status <> 'approved' then raise exception 'Payout must be approved first'; end if;
  if p.requested_by = auth.uid() then raise exception 'You cannot confirm a payout you requested' using errcode = '42501'; end if;
  if p.amount_cents >= cfg.payout_dual_control_cents and p.decided_by = auth.uid() then raise exception 'A second admin must confirm payouts of this size' using errcode = '42501'; end if;
  -- Re-check: refunds or chargebacks since approval may have reduced what is owed.
  bal := public.payout_balance_for(p.organization_id, p.user_id);
  if (bal->>'available_cents')::bigint + p.amount_cents < p.amount_cents then
    perform public.raise_exception_case('payout_exceeds_balance', p.id::text, 'critical', bal || jsonb_build_object('payout_cents', p.amount_cents), null, null, p.id);
    raise exception 'This payout is now larger than the available balance; it has been flagged for review';
  end if;
  update public.payouts set status = 'paid', paid_at = now(), bank_reference = left(btrim(p_reference), 120) where id = p_payout returning * into p;
  insert into public.ledger_entries (organization_id, payee_user, payout_id, kind, amount_cents, note) values (p.organization_id, p.user_id, p.id, 'payout', -p.amount_cents, 'Payout ' || coalesce(p_reference, ''));
  perform public.post_journal('payout', 'payout:' || p.id, jsonb_build_object('payout', p.id), jsonb_build_array(
    jsonb_build_object('account', 'organizer_payable', 'amount', p.amount_cents, 'org', p.organization_id, 'user', p.user_id),
    jsonb_build_object('account', 'platform_cash', 'amount', -p.amount_cents)), 'Payout ' || left(btrim(p_reference), 120));
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'payout.paid', 'payout', p.id, jsonb_build_object('amount_cents', p.amount_cents, 'approved_by', p.decided_by));
  perform public.notify(coalesce(p.user_id, p.requested_by), 'payout_update', null, 'payout', p.id, 'payout:' || p.id || ':paid');
end $$;

-- payout_balance as the payee sees it, for definer code acting on their behalf (bypasses the viewer check).
create or replace function public.payout_balance_for(p_org uuid, p_user uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare cfg public.platform_config; gross bigint; settled bigint; reductions bigint; paid bigint; pending bigint; disputed bigint; committed bigint;
begin
  select * into cfg from public.platform_config where id;
  select coalesce(sum(l.amount_cents), 0) into settled from public.ledger_entries l join public.events e on e.id = l.event_id
   where l.kind = 'sale' and l.organization_id is not distinct from p_org and l.payee_user is not distinct from p_user
     and e.status <> 'cancelled' and coalesce(e.ends_at, e.starts_at + interval '6 hours') + make_interval(days => cfg.settlement_hold_days) <= now();
  select coalesce(sum(l.amount_cents), 0) into reductions from public.ledger_entries l where l.kind in ('refund','chargeback','adjustment') and l.organization_id is not distinct from p_org and l.payee_user is not distinct from p_user;
  select coalesce(sum(-l.amount_cents), 0) into paid from public.ledger_entries l where l.kind = 'payout' and l.organization_id is not distinct from p_org and l.payee_user is not distinct from p_user;
  select coalesce(sum(p.amount_cents), 0) into pending from public.payouts p where p.status in ('requested','approved') and p.organization_id is not distinct from p_org and p.user_id is not distinct from p_user;
  select coalesce(sum(d.amount_cents), 0) into disputed from public.disputes d join public.orders o on o.id = d.order_id join public.events e on e.id = o.event_id
   where d.status = 'open' and e.organization_id is not distinct from p_org and (p_org is not null or e.host = p_user);
  select coalesce(sum((public.refund_split(o, r.ticket_amount_cents, 0)->>'organizer')::bigint), 0) into committed
    from public.refunds r join public.orders o on o.id = r.order_id join public.events e on e.id = o.event_id
   where r.kind <> 'oversold' and r.status in ('requested','approved','processing','manual_required')
     and e.organization_id is not distinct from p_org and (p_org is not null or (e.organization_id is null and e.host = p_user));
  return jsonb_build_object('available_cents', settled + reductions - paid - pending - disputed - committed, 'settled_sales_cents', settled, 'paid_out_cents', paid,
                            'pending_payout_cents', pending, 'open_disputes_cents', disputed, 'committed_refunds_cents', committed);
end $$;

create or replace function public.admin_add_adjustment(p_org uuid, p_user uuid, p_amount bigint, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(p_note, '') = '' then raise exception 'A note is required'; end if;
  if p_amount is null or p_amount = 0 then raise exception 'Amount cannot be zero'; end if;
  insert into public.ledger_entries (organization_id, payee_user, kind, amount_cents, note) values (p_org, p_user, 'adjustment', p_amount, left(p_note, 300));
  perform public.post_journal('adjustment', 'adjustment:' || gen_random_uuid(), '{}'::jsonb, jsonb_build_array(
    jsonb_build_object('account', 'organizer_payable', 'amount', -p_amount, 'org', p_org, 'user', p_user),
    jsonb_build_object('account', 'adjustments', 'amount', p_amount)), left(p_note, 300));
  insert into public.audit_log (actor, action, entity_type, detail) values (auth.uid(), 'ledger.adjustment', 'ledger', jsonb_build_object('org', p_org, 'user', p_user, 'amount_cents', p_amount, 'note', p_note));
end $$;

-- Fees now live in fee_policies; the old config keys are refused so nobody believes they changed pricing.
create or replace function public.admin_set_config(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p ? 'fee_bps' or p ? 'fee_fixed_cents' then raise exception 'Fees are set as versioned fee policies (Admin → Tickets & Trust → Terms)'; end if;
  update public.platform_config set
    hold_minutes = coalesce((p->>'hold_minutes')::int, hold_minutes), max_tickets_per_order = coalesce((p->>'max_tickets_per_order')::int, max_tickets_per_order),
    vat_registered = coalesce((p->>'vat_registered')::boolean, vat_registered), vat_rate_bps = coalesce((p->>'vat_rate_bps')::int, vat_rate_bps),
    vat_number = case when p ? 'vat_number' then nullif(p->>'vat_number', '') else vat_number end, legal_name = coalesce(nullif(p->>'legal_name', ''), legal_name),
    settlement_hold_days = coalesce((p->>'settlement_hold_days')::int, settlement_hold_days), payout_min_cents = coalesce((p->>'payout_min_cents')::int, payout_min_cents),
    buyer_refund_hours = coalesce((p->>'buyer_refund_hours')::int, buyer_refund_hours),
    require_sales_review = coalesce((p->>'require_sales_review')::boolean, require_sales_review),
    payout_dual_control_cents = coalesce((p->>'payout_dual_control_cents')::bigint, payout_dual_control_cents),
    payout_account_cooloff_hours = coalesce((p->>'payout_account_cooloff_hours')::int, payout_account_cooloff_hours)
  where id;
  if (select vat_registered and vat_number is null from public.platform_config where id) then raise exception 'A VAT number is required when VAT-registered'; end if;
  insert into public.audit_log (actor, action, entity_type, detail) values (auth.uid(), 'platform_config.updated', 'platform_config', p);
  return (select to_jsonb(c) - 'id' from public.platform_config c where id);
end $$;

-- ---------------------------------------------------------------- reconciliation
create or replace function public.finance_reconcile() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r record; n_before bigint; n_after bigint; expired integer;
begin
  -- Signed-in callers must be admins; the scheduler / service role has no user id (anon cannot execute this at all).
  if auth.uid() is not null and not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select count(*) into n_before from public.reconciliation_exceptions where status = 'open';
  expired := public.expire_orders();

  for r in select e.id from public.journal_entries e join public.journal_lines l on l.entry_id = e.id group by e.id having sum(l.amount_cents) <> 0 loop
    perform public.raise_exception_case('journal_unbalanced', r.id::text, 'critical', '{}'::jsonb);
  end loop;
  -- Orders paid too late for stock (refund kind 'oversold') never get tickets or a sale entry: their money sits in refunds_payable.
  for r in select o.id from public.orders o where o.status in ('paid', 'partially_refunded', 'refunded', 'disputed') and o.total_cents > 0
             and not exists (select 1 from public.journal_entries j where j.idempotency_key = 'sale:' || o.id)
             and not exists (select 1 from public.refunds rf where rf.order_id = o.id and rf.kind = 'oversold') loop
    perform public.raise_exception_case('missing_sale_journal', r.id::text, 'high', '{}'::jsonb, r.id);
  end loop;
  for r in select o.id, (select coalesce(sum(oi.qty * tt.group_size), 0) from public.order_items oi join public.ticket_types tt on tt.id = oi.ticket_type_id where oi.order_id = o.id) as want,
                  (select count(*) from public.tickets t where t.order_id = o.id) as got
             from public.orders o where o.status in ('paid', 'partially_refunded', 'refunded', 'disputed')
              and not exists (select 1 from public.refunds rf where rf.order_id = o.id and rf.kind = 'oversold') loop
    if r.want <> r.got then perform public.raise_exception_case('ticket_count_mismatch', r.id::text, 'critical', jsonb_build_object('expected', r.want, 'issued', r.got), r.id); end if;
  end loop;
  for r in select o.id from public.orders o where o.status in ('paid', 'partially_refunded', 'refunded', 'disputed') and o.total_cents > 0 and o.provider_ref is null loop
    perform public.raise_exception_case('paid_without_provider_reference', r.id::text, 'high', '{}'::jsonb, r.id);
  end loop;
  -- Organiser balance: the single-entry sub-ledger and the journal must agree, payee by payee.
  for r in select k.payee, sum(k.sub) as sub, sum(k.jrn) as jrn from (
             select coalesce(organization_id, payee_user)::text as payee, amount_cents as sub, 0::bigint as jrn from public.ledger_entries
             union all
             select coalesce(organization_id, payee_user)::text, 0, -amount_cents from public.journal_lines where account = 'organizer_payable') k
           group by k.payee having sum(k.sub) <> sum(k.jrn) loop
    perform public.raise_exception_case('payable_mismatch', r.payee, 'critical', jsonb_build_object('subledger_cents', r.sub, 'journal_cents', r.jrn));
  end loop;
  for r in select id, order_id, status from public.refunds where (status = 'processing' and coalesce(processed_at, decided_at, created_at) < now() - interval '1 hour')
             or (status in ('manual_required', 'approved') and coalesce(decided_at, created_at) < now() - interval '2 days') loop
    perform public.raise_exception_case('refund_stuck', r.id::text, 'high', jsonb_build_object('status', r.status), r.order_id, r.id);
  end loop;
  for r in select id from public.payouts where status = 'paid' and coalesce(bank_reference, '') = '' loop
    perform public.raise_exception_case('payout_without_reference', r.id::text, 'critical', '{}'::jsonb, null, null, r.id);
  end loop;

  select count(*) into n_after from public.reconciliation_exceptions where status = 'open';
  insert into public.audit_log (actor, action, entity_type, detail) values (auth.uid(), 'finance.reconciled', 'finance', jsonb_build_object('open_before', n_before, 'open_after', n_after, 'expired_orders', expired));
  return jsonb_build_object('open_exceptions', n_after, 'new_exceptions', greatest(0, n_after - n_before), 'expired_orders', expired);
end $$;

create or replace function public.admin_resolve_exception(p_id bigint, p_status text, p_resolution text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('resolved', 'dismissed') then raise exception 'bad status'; end if;
  if coalesce(char_length(btrim(p_resolution)), 0) < 5 then raise exception 'Describe what was done'; end if;
  update public.reconciliation_exceptions set status = p_status, resolution = left(p_resolution, 1000), resolved_by = auth.uid(), resolved_at = now() where id = p_id and status = 'open';
  if not found then raise exception 'Exception is not open'; end if;
  insert into public.audit_log (actor, action, entity_type, detail) values (auth.uid(), 'reconciliation.' || p_status, 'reconciliation_exception', jsonb_build_object('id', p_id, 'resolution', p_resolution));
end $$;

-- Ticketing numbers from the journal (what actually happened, by accounting basis), for a period plus current balances.
create or replace function public.admin_ticket_finance(p_from timestamptz default now() - interval '30 days', p_to timestamptz default now()) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare r jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  with period as (
    select l.account, e.kind, sum(l.amount_cents) as amt from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
     where e.created_at >= p_from and e.created_at < p_to group by 1, 2),
  bal as (select account, sum(amount_cents) as amt from public.journal_lines group by 1)
  select jsonb_build_object(
    'basis', 'Double-entry journal: provider-confirmed payments, completed refunds, recorded payouts. Pending checkouts are excluded.',
    'collected_cents', coalesce((select sum(amt) from period where account = 'platform_cash' and kind in ('sale', 'oversold_hold')), 0),
    'gross_ticket_sales_cents', coalesce((select sum(subtotal_cents) from public.orders where paid_at >= p_from and paid_at < p_to and status in ('paid', 'partially_refunded', 'refunded', 'disputed')), 0),
    'commission_revenue_cents', -coalesce((select sum(amt) from period where account = 'commission_revenue'), 0),
    'buyer_fee_revenue_cents', -coalesce((select sum(amt) from period where account = 'buyer_fee_revenue'), 0),
    'vat_on_platform_charges_cents', -coalesce((select sum(amt) from period where account = 'vat_payable'), 0),
    'refunds_paid_cents', -coalesce((select sum(amt) from period where account = 'platform_cash' and kind = 'refund'), 0),
    'chargebacks_cents', -coalesce((select sum(amt) from period where account = 'platform_cash' and kind = 'chargeback'), 0),
    'chargeback_losses_cents', coalesce((select sum(amt) from period where account = 'chargeback_losses'), 0),
    'payouts_completed_cents', -coalesce((select sum(amt) from period where account = 'platform_cash' and kind = 'payout'), 0),
    'net_platform_contribution_cents', -coalesce((select sum(amt) from period where account in ('commission_revenue', 'buyer_fee_revenue', 'chargeback_losses', 'adjustments')), 0),
    'processing_costs', 'Not recorded: provider fees are not yet imported from PayFast/Ozow statements.',
    'balances', jsonb_build_object(
      'cash_held_cents', coalesce((select amt from bal where account = 'platform_cash'), 0),
      'organizer_payable_cents', -coalesce((select amt from bal where account = 'organizer_payable'), 0),
      'refunds_owed_cents', -coalesce((select amt from bal where account = 'refunds_payable'), 0),
      'vat_payable_cents', -coalesce((select amt from bal where account = 'vat_payable'), 0)),
    'open_refund_obligations_cents', coalesce((select sum(ticket_amount_cents + fee_amount_cents) from public.refunds where status in ('requested', 'approved', 'processing', 'manual_required')), 0),
    'open_exceptions', (select count(*) from public.reconciliation_exceptions where status = 'open'),
    'events_awaiting_review', (select count(*) from public.events where sales_review in ('submitted', 'under_review'))
  ) into r;
  return r;
end $$;

-- ---------------------------------------------------------------- notifications for the ticket lifecycle
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check (type in
  ('friend_request', 'friend_accepted', 'reaction', 'comment', 'event_invite', 'rsvp', 'community_join', 'new_event', 'event_update', 'event_cancelled', 'live_started',
   'post_tag', 'memory_reaction', 'memory_reply', 'verified', 'security', 'campaign', 'org_member', 'org_rsvp', 'org_follow',
   'ticket_order', 'refund_update', 'sales_review', 'payout_update'));

-- Paid orders made before this migration get their sale journal (idempotent).
do $$ declare o public.orders; begin
  for o in select * from public.orders where status in ('paid', 'partially_refunded', 'refunded', 'disputed') and total_cents > 0 loop
    perform public.post_sale_journal(o);
  end loop;
end $$;

-- ---------------------------------------------------------------- media read rule: verification evidence files
-- Migration 26's rule, plus evidence uploads.
drop policy if exists media_select_visible on storage.objects;
create policy media_select_visible on storage.objects for select to authenticated
  using (
    bucket_id = 'media' and (
      (storage.foldername(objects.name))[1] = (select auth.uid())::text
      or exists (select 1 from public.posts p where p.media_path = objects.name or p.music_path = objects.name)
      or exists (select 1 from public.post_media pm where pm.path = objects.name or pm.poster_path = objects.name or pm.display_path = objects.name)
      or exists (select 1 from public.comments c where c.audio_path = objects.name or c.video_path = objects.name)
      or exists (select 1 from public.profiles pr where pr.avatar_path = objects.name or pr.cover_path = objects.name)
      or exists (select 1 from public.events e where e.cover_path = objects.name or e.hero_video_path = objects.name)
      or exists (select 1 from public.event_lineup l where l.image_path = objects.name)
      or exists (select 1 from public.communities c where c.cover_path = objects.name)
      or exists (select 1 from public.memories m where m.media_path = objects.name or m.music_path = objects.name)
      or exists (select 1 from public.memory_replies r where r.audio_path = objects.name)
      or exists (select 1 from public.messages m where m.media_path = objects.name or m.audio_path = objects.name)
      or exists (select 1 from public.organizations o where o.avatar_path = objects.name or o.cover_path = objects.name)
      or exists (select 1 from public.media_assets a where a.organization_id is not null and (a.path = objects.name or a.thumb_path = objects.name))
      or exists (select 1 from public.event_evidence ev where ev.file_path = objects.name)   -- migration 27: VYBE reviewers and the event's managers (row security on event_evidence decides)
    )
  );

-- ---------------------------------------------------------------- grants
revoke execute on function public.fee_policy_for(uuid, timestamptz), public.bps_of(bigint, integer), public.price_order(public.fee_policies, bigint, integer, boolean, integer),
  public.post_journal(text, text, jsonb, jsonb, text), public.post_sale_journal(public.orders), public.raise_exception_case(text, text, text, jsonb, uuid, uuid, uuid),
  public.record_payment_notification(text, text, text, text, bigint, text), public.finish_payment_notification(bigint, text), public.refund_split(public.orders, bigint, bigint),
  public.payout_balance_for(uuid, uuid), public.finance_reconcile(), public.issue_tickets(uuid, text, text, text), public.close_order(uuid, text) from public, anon, authenticated;
revoke execute on function public.admin_create_fee_policy(jsonb), public.preview_pricing(jsonb, bigint, integer), public.add_event_evidence(uuid, text, text, text),
  public.submit_event_for_sales_review(uuid, text), public.admin_review_event_sales(uuid, text, text), public.admin_decide_evidence(uuid, text, text),
  public.admin_set_lineup_status(uuid, text, text), public.can_scan_event(uuid), public.admit_ticket(uuid, text), public.my_ticket_code(uuid),
  public.admin_resolve_exception(bigint, text, text), public.admin_ticket_finance(timestamptz, timestamptz), public.event_fee_terms(uuid) from public, anon;
grant execute on function public.admin_create_fee_policy(jsonb), public.preview_pricing(jsonb, bigint, integer), public.add_event_evidence(uuid, text, text, text),
  public.submit_event_for_sales_review(uuid, text), public.admin_review_event_sales(uuid, text, text), public.admin_decide_evidence(uuid, text, text),
  public.admin_set_lineup_status(uuid, text, text), public.can_scan_event(uuid), public.admit_ticket(uuid, text), public.my_ticket_code(uuid),
  public.admin_resolve_exception(bigint, text, text), public.admin_ticket_finance(timestamptz, timestamptz), public.event_fee_terms(uuid) to authenticated;
-- finance_reconcile checks is_admin itself; signed-in admins call it from the portal.
grant execute on function public.finance_reconcile() to authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.record_payment_notification(text, text, text, text, bigint, text), public.finish_payment_notification(bigint, text),
      public.finance_reconcile(), public.close_order(uuid, text) to service_role;
  end if;
end $$;

-- Trigger functions are never callable over the API (also fixes trg_close_friends_limit from migration 26).
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig from pg_proc p
            where p.pronamespace = 'public'::regnamespace and p.prorettype in ('trigger'::regtype, 'event_trigger'::regtype) loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

commit;

select item, ok from (values
  ('launch terms carried over as fee policy v1 (buyer fee as before, no commission)', exists (select 1 from public.fee_policies f, public.platform_config c where f.scope = 'platform' and f.buyer_fee_bps = c.fee_bps and f.buyer_fee_fixed_cents = c.fee_fixed_cents and f.commission_bps = 0)),
  ('every journal entry balances', not exists (select 1 from public.journal_lines group by entry_id having sum(amount_cents) <> 0)),
  ('paid ticket sales need review; nobody can pre-approve their own event', (select require_sales_review from public.platform_config) and exists (select 1 from pg_trigger where tgname = 'event_review_insert') and not has_column_privilege('authenticated', 'public.events', 'sales_review', 'update')),
  ('ticket codes are no longer readable by organisers or scanners', not has_column_privilege('authenticated', 'public.tickets', 'code', 'select') and has_function_privilege('authenticated', 'public.my_ticket_code(uuid)', 'execute')),
  ('payment notifications and reconciliation are server-only', not has_table_privilege('authenticated', 'public.payment_notifications', 'insert') and not has_function_privilege('authenticated', 'public.record_payment_notification(text, text, text, text, bigint, text)', 'execute')),
  ('event-bound admission and door teams', has_function_privilege('authenticated', 'public.admit_ticket(uuid, text)', 'execute') and to_regclass('public.event_staff') is not null and to_regclass('public.ticket_scans') is not null),
  ('no trigger function callable over the API', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prorettype = 'trigger'::regtype and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))))
) as v(item, ok);
